#include <bits/stdc++.h>
using namespace std;

int n, m, nr = 1, nc = 1;
vector<vector<long long>> tree;

// Max over rows [top, bottom] x cols [left, right] using an iterative 2D segment tree.
long long query(long long top, long long bottom, long long left, long long right) {
    if (top > bottom || left > right) return 0;
    long long res = 0;
    int t = top + nr, b = bottom + nr + 1;
    auto rowMax = [&](int node) {
        int a = left + nc, c = right + nc + 1;
        while (a < c) {
            if (a & 1) res = max(res, tree[node][a++]);
            if (c & 1) res = max(res, tree[node][--c]);
            a >>= 1; c >>= 1;
        }
    };
    while (t < b) {
        if (t & 1) rowMax(t++);
        if (b & 1) rowMax(--b);
        t >>= 1; b >>= 1;
    }
    return res;
}

int main() {
    scanf("%d %d", &n, &m);
    vector<vector<long long>> g(n, vector<long long>(m));
    for (auto &row : g)
        for (auto &x : row) scanf("%lld", &x);
    while (nr < n) nr *= 2;
    while (nc < m) nc *= 2;
    tree.assign(2 * nr, vector<long long>(2 * nc, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) tree[nr + i][nc + j] = g[i][j];
        for (int j = nc - 1; j > 0; j--) tree[nr + i][j] = max(tree[nr + i][2 * j], tree[nr + i][2 * j + 1]);
    }
    for (int i = nr - 1; i > 0; i--)
        for (int j = 1; j < 2 * nc; j++) tree[i][j] = max(tree[2 * i][j], tree[2 * i + 1][j]);
    vector<pair<int, int>> found;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            long long v = g[i][j];
            if (v == 0) continue;
            // Middle rows keep the full width; the two border rows drop their corner columns.
            long long big = query(max(0LL, i - v + 1), min<long long>(n - 1, i + v - 1), max(0LL, j - v), min<long long>(m - 1, j + v));
            for (long long row : {i - v, i + v})
                if (row >= 0 && row < n)
                    big = max(big, query(row, row, max(0LL, j - v + 1), min<long long>(m - 1, j + v - 1)));
            if (big <= v) found.push_back({i, j});
        }
    }
    printf("%d\n", (int)found.size());
    for (auto [i, j] : found) printf("%d %d\n", i, j);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    static int n, m, nr = 1, nc = 1;
    static long[][] tree;

    static long rowMax(int node, long left, long right, long res) {
        int a = (int) left + nc, c = (int) right + nc + 1;
        while (a < c) {
            if ((a & 1) != 0) res = Math.max(res, tree[node][a++]);
            if ((c & 1) != 0) res = Math.max(res, tree[node][--c]);
            a >>= 1; c >>= 1;
        }
        return res;
    }

    // Max over rows [top, bottom] x cols [left, right] using an iterative 2D segment tree.
    static long query(long top, long bottom, long left, long right) {
        if (top > bottom || left > right) return 0;
        long res = 0;
        int t = (int) top + nr, b = (int) bottom + nr + 1;
        while (t < b) {
            if ((t & 1) != 0) res = rowMax(t++, left, right, res);
            if ((b & 1) != 0) res = rowMax(--b, left, right, res);
            t >>= 1; b >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        n = nextInt(); m = nextInt();
        long[][] g = new long[n][m];
        for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) g[i][j] = nextLong();
        while (nr < n) nr *= 2;
        while (nc < m) nc *= 2;
        tree = new long[2 * nr][2 * nc];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) tree[nr + i][nc + j] = g[i][j];
            for (int j = nc - 1; j > 0; j--) tree[nr + i][j] = Math.max(tree[nr + i][2 * j], tree[nr + i][2 * j + 1]);
        }
        for (int i = nr - 1; i > 0; i--)
            for (int j = 1; j < 2 * nc; j++) tree[i][j] = Math.max(tree[2 * i][j], tree[2 * i + 1][j]);
        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                long v = g[i][j];
                if (v == 0) continue;
                // Middle rows keep the full width; the two border rows drop their corner columns.
                long big = query(Math.max(0, i - v + 1), Math.min(n - 1, i + v - 1), Math.max(0, j - v), Math.min(m - 1, j + v));
                for (long row : new long[] {i - v, i + v})
                    if (row >= 0 && row < n)
                        big = Math.max(big, query(row, row, Math.max(0, j - v + 1), Math.min(m - 1, j + v - 1)));
                if (big <= v) { count++; sb.append(i).append(' ').append(j).append('\n'); }
            }
        }
        System.out.print(count + "\n" + sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

var n, m, nr, nc int
var tree [][]int

// Max over rows [top, bottom] x cols [left, right] using an iterative 2D segment tree.
func query(top, bottom, left, right int) int {
	if top > bottom || left > right {
		return 0
	}
	res := 0
	rowMax := func(node int) {
		a, c := left+nc, right+nc+1
		for a < c {
			if a&1 == 1 {
				res = max(res, tree[node][a])
				a++
			}
			if c&1 == 1 {
				c--
				res = max(res, tree[node][c])
			}
			a >>= 1
			c >>= 1
		}
	}
	t, b := top+nr, bottom+nr+1
	for t < b {
		if t&1 == 1 {
			rowMax(t)
			t++
		}
		if b&1 == 1 {
			b--
			rowMax(b)
		}
		t >>= 1
		b >>= 1
	}
	return res
}

func main() {
	n, m = readInt(), readInt()
	g := make([][]int, n)
	for i := range g {
		g[i] = make([]int, m)
		for j := range g[i] {
			g[i][j] = readInt()
		}
	}
	nr, nc = 1, 1
	for nr < n {
		nr *= 2
	}
	for nc < m {
		nc *= 2
	}
	tree = make([][]int, 2*nr)
	for i := range tree {
		tree[i] = make([]int, 2*nc)
	}
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			tree[nr+i][nc+j] = g[i][j]
		}
		for j := nc - 1; j > 0; j-- {
			tree[nr+i][j] = max(tree[nr+i][2*j], tree[nr+i][2*j+1])
		}
	}
	for i := nr - 1; i > 0; i-- {
		for j := 1; j < 2*nc; j++ {
			tree[i][j] = max(tree[2*i][j], tree[2*i+1][j])
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	type cell struct{ i, j int }
	found := []cell{}
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			v := g[i][j]
			if v == 0 {
				continue
			}
			// Middle rows keep the full width; the two border rows drop their corner columns.
			big := query(max(0, i-v+1), min(n-1, i+v-1), max(0, j-v), min(m-1, j+v))
			for _, row := range []int{i - v, i + v} {
				if row >= 0 && row < n {
					big = max(big, query(row, row, max(0, j-v+1), min(m-1, j+v-1)))
				}
			}
			if big <= v {
				found = append(found, cell{i, j})
			}
		}
	}
	fmt.Fprintln(w, len(found))
	for _, c := range found {
		fmt.Fprintln(w, c.i, c.j)
	}
}
